"""Saved-only consequence table; fixed review identities, no scientific fitting."""
import argparse,json,gzip
from pathlib import Path
import numpy as np,yaml
from report_step_campaign import stats

def main(root,out):
 p=root/'report/N14-REF-rep2';w=json.loads((p/'windows.json').read_text());z=np.load(p/'windows.npz');ep=p/'event-chain.yaml';events=yaml.load(ep.read_bytes() if ep.exists() else gzip.decompress(Path(str(ep)+'.gz').read_bytes()),Loader=yaml.CSafeLoader);pop={n['network']:n for n in json.loads((p/'population.json').read_text())};rows=[]
 for q in w:
  get=lambda k:z[q['key']+'_'+k];valid=get('valid_x');retained=(get('state')&1)!=0;source=get('source');cal=get('CAL');t5=get('T5_residual');stage={k:stats(get(k),get('native_row'),q['center']) for k in ('CAL','M0','T5_residual')};event=next((e for e in events if e['network']==q['network'] and e['event']==q['event']),None) if q['kind']=='event' else None
  nlearn=sum(len(t['raw_candidates_in_window']) for t in q['learn_trace']);reason=('; '.join(t['consider_class'] for t in q['learn_trace']) if q['learn_trace'] else 'no raw candidate or trial overlap in this excerpt; other detector events may still exclude it')
  if event:
   cs=event['chain']['coordinates'];reason+='; x/r amplitude '+str([c['amplitude_cause'] for c in cs])+', consistency '+str([c['consistency_cause'] for c in cs])+', admission '+str([c['admission_cause'] for c in cs])
  if not np.isfinite(t5).any():disposition='potentially costly treatment requiring a comparison';limit='RTC withholds this excerpt; residual unavailable, no demonstrated recoverable scientific information'
  elif q['key']=='n1_w5':disposition='not established';limit='off-center excursion is strongly suppressed by PTC; local outliers remain, but source/map harm and benefit of another RTC operation are not established'
  else:disposition='adequate at the measured scale';limit='PTC/local-noise comparison is descriptive; no RTC benefit or PTC penalty established without intervention'
  finite=t5[np.isfinite(t5)];shape_stats=dict(T5_p05=float(np.quantile(finite,.05)) if len(finite) else None,T5_p50=float(np.median(finite)) if len(finite) else None,T5_p95=float(np.quantile(finite,.95)) if len(finite) else None)
  rows.append(dict(key=q['key'],network=q['network'],channel=q['channel'],event=q['event'],evidence=q['adjudication'],raw_candidates_in_excerpt=nlearn,reason=reason,valid_detector_seconds=float(valid.sum()*.008192),RTC_retained_detector_seconds=float((retained&valid).sum()*.008192),source_cells=int((source&valid).sum()),source_RTC_lost_cells=int((source&valid&~retained).sum()),overlapping_exclusions={k:int((get(k)&valid).sum()) for k in ('transition','fitting_guard','jump_scan','operation_unavailable')},stage=stage,**shape_stats,disposition=disposition,attribution_limit=limit,source_noise_cost_context='No per-event map transfer, estimator uncertainty or CPU attribution; use branch response and network union/timing tables.'))
 def f(v):return 'unavailable' if v is None else f'{v:.2f}'
 lines=['# Frozen 32-window consequence table','', 'All intervals are the original frozen selections; no extra event windows. x/r evidence is original Δf/f. RTC exposure uses valid x and native 8.192 ms integration. CAL/M0/T5 values below are mJy/beam; C = post-minus-pre median excluding ±12 rows around the declared center, N = adjacent finite-difference MAD. Off-center edges, slopes and colored noise can invalidate a step interpretation of C/N; it is not significance. Excluded residuals are unavailable. Source counts use own M0 geometric context, not optical protection. No per-event causal transfer/noise/cost measurement was made.','', 'Cause codes: amplitude 0 not seeded, 1 background unavailable, 4 below threshold, 5 passes; consistency 0 primary not passed, 1 short fit unavailable, 3 short below threshold, 4 sign disagreement, 5 offset disagreement, 6 passes; admission 0 measurement unavailable, 6 admitted. Complete chains preserve all codes and refit/reassessment support.','', '| Window / channel / class | Original evidence; Learn/Consider | RTC action, detector-s and source cells | CAL → M0 → T5 residual C; T5 N | Consequence / limit |','|---|---|---|---|---|']
 for r in rows:
  stages=' → '.join(f(r['stage'][k]['post_minus_pre']) for k in ('CAL','M0','T5_residual'));N=f(r['stage']['T5_residual']['adjacent_difference_MAD']);e=r['evidence'];lines.append(f"| {r['key']} / {r['channel']} / {e['label']} | {e['reason']} Learn candidates {r['raw_candidates_in_excerpt']}; {r['reason']} | retained {r['RTC_retained_detector_seconds']:.3f}/{r['valid_detector_seconds']:.3f}; source lost {r['source_RTC_lost_cells']}/{r['source_cells']}; masks {r['overlapping_exclusions']} | {stages}; N {N} | **{r['disposition']}**. {r['attribution_limit']} |")
 out.mkdir(parents=True,exist_ok=True);(out/'CONSEQUENCES.md').write_text('\n'.join(lines)+'\n');(out/'consequences.json').write_text(json.dumps(rows,indent=2,allow_nan=False)+'\n')
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();main(a.root,a.output)
